-- Insert Quiz Questions for Lesson: Prepare the Account and Plan the Sale

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 11 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 11 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'prepare-account-plan-sale' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson prepare-account-plan-sale not found in module 11';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check before creating products or payment links?', 
    '["Only the product name","Payment provider connection, business details, and test vs live mode","Just your social media accounts","Nothing, you can start immediately"]'::jsonb,
    'Payment provider connection, business details, and test vs live mode',
    'Before creating products, check your payment provider connection, business and invoice details, and understand the difference between test mode and live mode.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between test mode and live mode?', 
    '["There is no difference","Test mode simulates payment without charging; live mode processes real transactions","Test mode is more expensive","Live mode is only for testing"]'::jsonb,
    'Test mode simulates payment without charging; live mode processes real transactions',
    'Test mode simulates payment without charging a real card. Live mode processes actual customer transactions. Always test in test mode first.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the CLEAR offer check stand for?', 
    '["Create, Launch, Earn, Analyze, Repeat","Customer, Label, Exact amount, Arrangement, Result","Cash, Login, Email, Account, Receipt","Company, Location, Employees, Assets, Revenue"]'::jsonb,
    'Customer, Label, Exact amount, Arrangement, Result',
    'CLEAR stands for: Customer (who is buying), Label (is the name clear), Exact amount (is the price correct), Arrangement (one-time or recurring), Result (what happens after payment).', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


