-- Insert Quiz Questions for Lesson: Create a Simple Product

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 11 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 11 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-simple-product' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-simple-product not found in module 11';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should a product be created before a payment link?', 
    '["Payment links are not necessary","The payment link needs a saved product and price to display what the buyer is purchasing","Products automatically create payment links","Invoices do not need products"]'::jsonb,
    'The payment link needs a saved product and price to display what the buyer is purchasing',
    'A payment link needs a saved product and price to display what the buyer is purchasing and how much they will pay. The product must exist first.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What makes a good product name?', 
    '["Internal codes like PRD-001","Clear, descriptive names buyers understand like ''Leadership Coaching Session — 60 Minutes''","Vague labels like ''Coaching'' or ''Plan A''","Random numbers and letters"]'::jsonb,
    'Clear, descriptive names buyers understand like ''Leadership Coaching Session — 60 Minutes''',
    'Good product names are clear and descriptive so buyers understand what they are purchasing. Avoid internal codes and vague labels.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check after saving a product?', 
    '["Nothing, it is automatically correct","Name, description, amount, currency, payment type, tax settings, and availability","Only the product image","Just the creation date"]'::jsonb,
    'Name, description, amount, currency, payment type, tax settings, and availability',
    'After saving, reopen the product and verify: name is correct, description is clear, amount and currency are correct, price is one-time (if intended), tax settings match, and product is active.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


