-- Insert Quiz Questions for Lesson: Prepare and Send a Simple Invoice

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 11 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 11 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'prepare-send-invoice' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson prepare-send-invoice not found in module 11';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check before sending an invoice?', 
    '["Only the total amount","Customer identity, invoice number, values, offer description, dates, payment method, and email experience","Just the invoice number","Nothing, invoices are always correct"]'::jsonb,
    'Customer identity, invoice number, values, offer description, dates, payment method, and email experience',
    'Use the INVOICE check: Identity (correct customer), Number (correct invoice number), Value (subtotal, tax, discount, total), Offer (clear description), Important dates, Collection method, Email and experience.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it critical to verify the customer before sending an invoice?', 
    '["It does not matter who receives it","An invoice sent to the wrong contact creates privacy and payment problems","Invoices are always private","Wrong recipients get discounts"]'::jsonb,
    'An invoice sent to the wrong contact creates privacy and payment problems',
    'Sending an invoice to the wrong contact creates serious privacy issues and payment problems. Always verify the recipient before sending.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the ''E'' in INVOICE stand for?', 
    '["Everything is fine","Email and experience","End of invoice","Extra charges"]'::jsonb,
    'Email and experience',
    'The E in INVOICE stands for Email and experience: Is the sending address correct, and does the preview look professional?', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


