-- Insert Quiz Questions for Lesson: Create and Share a Payment Link

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 11 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 11 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-share-payment-link' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-share-payment-link not found in module 11';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the LINK check stand for?', 
    '["Login, Invoice, Number, Knowledge","Label, Information, Number, Keep going","Launch, Integrate, Notify, Collect","List, Itemize, Note, Know"]'::jsonb,
    'Label, Information, Number, Keep going',
    'LINK stands for: Label (correct offer name), Information (clear description and fields), Number (correct amount, currency, quantity), Keep going (buyer knows what happens after payment).', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you NOT use a general payment link?', 
    '["When the offer and price are fixed","When the amount is different for each buyer or the offer contains private information","When you want to share on social media","When you have a saved product"]'::jsonb,
    'When the amount is different for each buyer or the offer contains private information',
    'Do not use a general payment link when: amount varies per buyer, buyer needs PO first, offer has private info, terms were negotiated differently, or the link would expose a non-public offer. Use an invoice instead.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why preview the payment link on mobile?', 
    '["Mobile preview is not important","Many buyers will complete purchases on mobile devices","Desktop preview is enough","Mobile links work differently"]'::jsonb,
    'Many buyers will complete purchases on mobile devices',
    'Many buyers complete purchases on mobile devices. Always preview your payment link on both desktop and mobile to ensure a good experience on all screen sizes.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


